 // Reports over the whole store.
+import { dayOf } from "../dates.js";
 import { listItems } from "./items.js";

+const SALE_REF = "sale:";
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** The ledger `ref` of stock used by a till ticket. */
+export function saleRef(ticket) {
+  return `${SALE_REF}${ticket}`;
+}
+
+/**
+ * Per item between two days (inclusive): theoretical use from sales, actual
+ * use from every consume movement, and the difference (actual - theoretical).
+ */
+export function varianceReport(store, from, to) {
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const byItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    const line = byItem.get(itemId) ?? { theoretical: 0, actual: 0 };
+    line.actual += m.qty;
+    if (m.ref.startsWith(SALE_REF)) line.theoretical += m.qty;
+    byItem.set(itemId, line);
+  }
+  return [...byItem]
+    .map(([itemId, l]) => ({ itemId, theoretical: round3(l.theoretical), actual: round3(l.actual), difference: round3(l.actual - l.theoretical) }))
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
